import{_ as e,c as r,o as h,ah as i}from"./chunks/framework.Dnh4IO1K.js";const p=JSON.parse('{"title":"姤","description":"周易正义 - 姤","frontmatter":{"title":"姤","description":"周易正义 - 姤"},"headers":[],"relativePath":"zh/classics/zhengyi/044.md","filePath":"zh/classics/zhengyi/044.md"}'),l={name:"zh/classics/zhengyi/044.md"};function n(d,a,t,o,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<blockquote><p>天风姤</p></blockquote><blockquote><p>卦辞：女壮，勿用取女。</p></blockquote><blockquote><p>彖曰：姤，遇也，柔遇刚也。勿用取女，不可与长也。天地相遇，品物咸章也。刚遇中正，天下大行也。姤之时义大矣哉！</p></blockquote><h1 id="姤" tabindex="-1">姤 <a class="header-anchor" href="#姤" aria-label="Permalink to “姤”">​</a></h1><h3 id="疏" tabindex="-1">疏 <a class="header-anchor" href="#疏" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“姤，遇也。”此卦一柔而遇五刚，故名为“姤”。施之於人，则是一女而遇五男，为壮至甚，故戒之曰“此女壮甚，勿用取此女”也。</p><h2 id="《彖》曰-​" tabindex="-1">《彖》曰： ​ <a class="header-anchor" href="#《彖》曰-​" aria-label="Permalink to “《彖》曰： ​”">​</a></h2><h3 id="姤-遇也。柔遇刚也。-​" tabindex="-1">姤，遇也。柔遇刚也。 ​ <a class="header-anchor" href="#姤-遇也。柔遇刚也。-​" aria-label="Permalink to “姤，遇也。柔遇刚也。 ​”">​</a></h3><p>王弼：施之於人，即女遇男也。一女而遇五男，为壮至甚，故不可取也。</p><h3 id="疏-1" tabindex="-1">疏 <a class="header-anchor" href="#疏-1" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：此就爻释卦名，以初六一柔而上遇五刚，所以名“遇”，而用释卦辞“女壮，勿用取女”之义也。</p><h3 id="勿用取女-不可与长也。天地相遇-品物咸章也。-​" tabindex="-1">“勿用取女”，不可与长也。天地相遇，品物咸章也。 ​ <a class="header-anchor" href="#勿用取女-不可与长也。天地相遇-品物咸章也。-​" aria-label="Permalink to ““勿用取女”，不可与长也。天地相遇，品物咸章也。 ​”">​</a></h3><p>王弼：正乃功成也。</p><h3 id="疏-2" tabindex="-1">疏 <a class="header-anchor" href="#疏-2" aria-label="Permalink to “疏”">​</a></h3><p>“勿用取女”至“品物咸章也”。○正义曰：“勿用取女，不可与长”者，女之为体，婉娩贞顺，方可期之偕老。淫壮若此，不可与之长久，故“勿用取女”。“天地相遇，品物咸章”者，已下广明遇义。卦得遇名，本由一柔与五刚相遇，故遇辞非美，就卦而取，遂言遇不可用，是“勿用取女”也。故孔子更就天地叹美“遇”之为义不可废也。天地若各亢所处，不相交遇，则万品庶物，无由彰显，必须二气相遇，乃得化生，故曰：“天地相遇，品物咸章”。</p><h3 id="刚遇中正-天下大行也。化乃大行也。-​" tabindex="-1">刚遇中正，天下大行也。化乃大行也。 ​ <a class="header-anchor" href="#刚遇中正-天下大行也。化乃大行也。-​" aria-label="Permalink to “刚遇中正，天下大行也。化乃大行也。 ​”">​</a></h3><h3 id="疏-3" tabindex="-1">疏 <a class="header-anchor" href="#疏-3" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：庄氏云：“一女而遇五男，既不可取，天地匹配，则能成品物。”由是言之，若刚遇中正之柔，男得幽贞之女，则天下人伦之化，乃得大行也。</p><h3 id="《姤》之时义大矣哉-​" tabindex="-1">《姤》之时义大矣哉！ ​ <a class="header-anchor" href="#《姤》之时义大矣哉-​" aria-label="Permalink to “《姤》之时义大矣哉！ ​”">​</a></h3><p>王弼：凡言义者，不尽於所见，中有意谓者也。</p><h3 id="疏-4" tabindex="-1">疏 <a class="header-anchor" href="#疏-4" aria-label="Permalink to “疏”">​</a></h3><p>“姤之时义大矣哉”！正义曰：上既博美，此又结叹，欲就卦而取义。但是一女而遇五男，不足称美，博论“天地相遇”，乃致“品物咸章”，然后“姤之时义大矣哉”！。○注“凡言义者”至“有意谓者也”。○正义曰：《注》总为称义发例，故曰“凡言”也。就卦以验名义，只是女遇於男，博寻遇之深旨，乃至道该天地，故云“不尽於所见，中有意谓”者也。</p><h2 id="《象》曰-天下有风-姤。后以施命诰四方。-​" tabindex="-1">《象》曰：天下有风，姤。后以施命诰四方。 ​ <a class="header-anchor" href="#《象》曰-天下有风-姤。后以施命诰四方。-​" aria-label="Permalink to “《象》曰：天下有风，姤。后以施命诰四方。 ​”">​</a></h2><h3 id="疏-5" tabindex="-1">疏 <a class="header-anchor" href="#疏-5" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：风行天下，则无物不遇，故为遇象。“后以施命诰四方”者，风行草偃，天之威令，故人君法此，以施教命，诰於四方也。</p><h2 id="初六-系于金柅-贞吉。有攸往-见凶。羸豕孚蹢躅。-​" tabindex="-1">初六：系于金柅，贞吉。有攸往，见凶。羸豕孚蹢躅。 ​ <a class="header-anchor" href="#初六-系于金柅-贞吉。有攸往-见凶。羸豕孚蹢躅。-​" aria-label="Permalink to “初六：系于金柅，贞吉。有攸往，见凶。羸豕孚蹢躅。 ​”">​</a></h2><p>王弼：金者，坚刚之物。尼者，制动之主，谓九四也。初六处遇之始，以一柔而承五刚，体夫躁质，得遇而通，散而无主，自纵者也。柔之为物，不可以不牵。臣妾之道，不可以不贞，故必系于正应，乃得“贞吉”也。若不牵于一，而有攸往行，则唯凶是见矣。羸豕，谓牝豕也。群豕之中，豭强而牝弱，故谓之“羸豕”也。孚，犹务躁也。夫阴质而躁恣者，羸豕特甚焉，言以不贞之阴，失其所牵，其为淫丑，若羸豕之孚务蹢躅也。</p><h3 id="疏-6" tabindex="-1">疏 <a class="header-anchor" href="#疏-6" aria-label="Permalink to “疏”">​</a></h3><p>“初六系于金柅”至“羸豕孚蹢躅”。○正义曰：系于金柅，贞吉”者，金者，坚刚之物。柅者，制动之主，谓九四也。初六阴质，若系於正，应以从於四，则贞而吉矣，故曰“系于金柅，贞吉”也。“有攸往，见凶”者，若不牵於一，而有所行往，则惟凶是见矣，故曰“有攸往，见凶”。“羸豕孚蹢躅”者，初六处遇之初，以一柔而承五刚，是不系金柅，有所往者也。不系而往，则如羸豕之务躁而蹢躅然也，故曰：“羸豕孚蹢躅”。羸豕谓牝豕也。群豕之中，豭强而牝弱也，故谓牝豕为羸豕。阴质而淫躁，牝豕特甚焉，故取以为喻。○注“柅者，制动之主”。○正义曰：“柅者，制动之主”。柅之为物，众说不同。王肃之徒皆为织绩之器，妇人所用。惟马云：“柅者，在车之下，所以止轮令不动者也。”王注云：“柅，制动之主。”盖与马同。</p><h3 id="《象》曰-系于金柅-柔道牵也。-​" tabindex="-1">《象》曰：“系于金柅”，柔道牵也。 ​ <a class="header-anchor" href="#《象》曰-系于金柅-柔道牵也。-​" aria-label="Permalink to “《象》曰：“系于金柅”，柔道牵也。 ​”">​</a></h3><h3 id="疏-7" tabindex="-1">疏 <a class="header-anchor" href="#疏-7" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“柔道牵”者，阴柔之道，必须有所牵系也。</p><h2 id="九二-包有鱼-无咎-不利宾。-​" tabindex="-1">九二：包有鱼，无咎，不利宾。 ​ <a class="header-anchor" href="#九二-包有鱼-无咎-不利宾。-​" aria-label="Permalink to “九二：包有鱼，无咎，不利宾。 ​”">​</a></h2><p>王弼：初阴而穷下，故称“鱼”。不正之阴，处遇之始，不能逆近者也。初自乐来应已之厨，非为犯夺，故“无咎”也。擅人之物，以为已惠，义所不为，故“不利宾”也。</p><h3 id="疏-8" tabindex="-1">疏 <a class="header-anchor" href="#疏-8" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“庖有鱼、无咎”者，初六以阴而处下，故称鱼也。以不正之阴，处遇之始，不能逆於所近，故舍九四之正应，乐充九二之庖厨，故曰“九二、庖有鱼”。初自乐来，为已之厨，非为犯夺，故得“无咎”也。“不利宾者”，夫擅人之物，以为己惠，义所不为，故“不利宾”也。</p><h3 id="《象》曰-包有鱼-义不及宾也。-​" tabindex="-1">《象》曰：“包有鱼”，义不及宾也。 ​ <a class="header-anchor" href="#《象》曰-包有鱼-义不及宾也。-​" aria-label="Permalink to “《象》曰：“包有鱼”，义不及宾也。 ​”">​</a></h3><h3 id="疏-9" tabindex="-1">疏 <a class="header-anchor" href="#疏-9" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“义不及宾”者，言有他人之物，於义不可及宾也。</p><h2 id="九三-臀无肤-其行次且-厉-无大咎。-​" tabindex="-1">九三：臀无肤，其行次且，厉，无大咎。 ​ <a class="header-anchor" href="#九三-臀无肤-其行次且-厉-无大咎。-​" aria-label="Permalink to “九三：臀无肤，其行次且，厉，无大咎。 ​”">​</a></h2><p>王弼：处下体之极，而二据於初，不为已乘，居不获安，行为其应，不能牵据，以固所处，故曰“臀无肤，其行次且”也。然履得其位，非为妄处，不遇其时，故使危厉。灾非已招，是以“无大咎”也。</p><h3 id="疏-10" tabindex="-1">疏 <a class="header-anchor" href="#疏-10" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：阳之所据者，阴也。九三处下体之上，为内卦之主，以乘於二，无阴可据，居不获安，上又无应，不能牵据以固所处，同於夬卦九四之失据，故曰“臀无肤，其行次且”也。然复得其位，非为妄处，特以不遇其时，故致此危厉，灾非已招，故无大咎，故曰“厉无大咎”。</p><h3 id="《象》曰-其行次且-行未牵也。-​" tabindex="-1">《象》曰：“其行次且”，行未牵也。 ​ <a class="header-anchor" href="#《象》曰-其行次且-行未牵也。-​" aria-label="Permalink to “《象》曰：“其行次且”，行未牵也。 ​”">​</a></h3><h3 id="疏-11" tabindex="-1">疏 <a class="header-anchor" href="#疏-11" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“行未牵”者，未能牵据，故“其行次且”，是“行未牵也”。</p><h2 id="九四-包无鱼-起凶。-​" tabindex="-1">九四：包无鱼，起凶。 ​ <a class="header-anchor" href="#九四-包无鱼-起凶。-​" aria-label="Permalink to “九四：包无鱼，起凶。 ​”">​</a></h2><p>王弼：二有其鱼，故失之也。无民而动，失应而作，是以“凶”也。</p><h3 id="疏-12" tabindex="-1">疏 <a class="header-anchor" href="#疏-12" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“庖无鱼”者，二擅其应，故曰“庖无鱼”也。庖之无鱼，则是无民之义也。“起凶”者，起，动也。“无民而动，失应而作，是以凶也。”</p><h3 id="《象》曰-无鱼-之凶-远民也。-​" tabindex="-1">《象》曰：“无鱼”之凶，远民也。 ​ <a class="header-anchor" href="#《象》曰-无鱼-之凶-远民也。-​" aria-label="Permalink to “《象》曰：“无鱼”之凶，远民也。 ​”">​</a></h3><h3 id="疏-13" tabindex="-1">疏 <a class="header-anchor" href="#疏-13" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“远民”者，阴为阳之民，为二所据，故曰“远民”也。</p><h2 id="九五-以杞包瓜-含章-有陨自天。-​" tabindex="-1">九五：以杞包瓜，含章，有陨自天。 ​ <a class="header-anchor" href="#九五-以杞包瓜-含章-有陨自天。-​" aria-label="Permalink to “九五：以杞包瓜，含章，有陨自天。 ​”">​</a></h2><p>王弼：杞之为物，生於肥地者也。包瓜为物，系而不食者也。九五履得尊位，而不遇其应，得地而不食，含章而未发，不遇其应，命未流行。然处得其所，体刚居中，志不舍命，不可倾陨，故曰“有陨自天”也。</p><h3 id="疏-14" tabindex="-1">疏 <a class="header-anchor" href="#疏-14" aria-label="Permalink to “疏”">​</a></h3><p>“九五以杞包瓜”至“有陨自天”。○正义曰：“以杞匏瓜”者，杞之为物，生於肥地；匏瓜为物，系而不食，九五处得尊位而不遇，其应是得地而不食，故曰“以杞匏瓜”也。“含章，有陨自天”者，不遇其应，命未流行，无物发起其美，故曰“含章”。然体刚居中，虽复当位，命未流行，而不能改其操，无能倾陨之者，故曰：“有陨自天”，盖言惟天能陨之耳。○注“杞之为物，生於肥地者也”。○正义曰：“杞之为物，生於肥地者也”，先儒说杞，亦有不同。马云：“杞，大木也。”《左传》云：“杞梓皮革自楚注，则为杞梓之杞。”子夏《传》曰：“作杞匏瓜。”薛虞《记》云：“杞，杞柳也。杞性柔刃，宜屈桡，似匏瓜。”又为杞柳之杞。案：王氏云“生於肥地”，盖以杞为今之枸杞也。</p><h3 id="《象》曰-九五-含章-中正也。-有陨自天-志不舍命也。-​" tabindex="-1">《象》曰：九五“含章”，中正也。“有陨自天”，志不舍命也。 ​ <a class="header-anchor" href="#《象》曰-九五-含章-中正也。-有陨自天-志不舍命也。-​" aria-label="Permalink to “《象》曰：九五“含章”，中正也。“有陨自天”，志不舍命也。 ​”">​</a></h3><h3 id="疏-15" tabindex="-1">疏 <a class="header-anchor" href="#疏-15" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“中正”者，中正故有美，无应故“含章”，而不发。若非九五中正，则无美可含，故举爻位而言“中正”也。“志不舍命”者，虽命未流行，而居尊当位，“志不舍命”，故曰“不可倾陨”也。</p><h2 id="上九-姤其角-吝-无咎。-​" tabindex="-1">上九：姤其角，吝，无咎。 ​ <a class="header-anchor" href="#上九-姤其角-吝-无咎。-​" aria-label="Permalink to “上九：姤其角，吝，无咎。 ​”">​</a></h2><p>王弼：进之於极，无所复遇，遇角而已，故曰“姤其角”也。进而无遇，独恨而已，不与物争，其道不害，故无凶咎也。</p><h3 id="疏-16" tabindex="-1">疏 <a class="header-anchor" href="#疏-16" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“姤其角”者，角者，最处体上，上九进之於极，无所复遇，遇角而已，故曰“姤其角”也。“吝无咎”者，角非所安，与无遇等，故独恨而鄙吝也。然不与物争，其道不害，故无凶咎，故曰“无咎”也。</p><h3 id="《象》曰-姤其角-上穷吝也。-​" tabindex="-1">《象》曰：“姤其角”，上穷吝也。 ​ <a class="header-anchor" href="#《象》曰-姤其角-上穷吝也。-​" aria-label="Permalink to “《象》曰：“姤其角”，上穷吝也。 ​”">​</a></h3><h3 id="疏-17" tabindex="-1">疏 <a class="header-anchor" href="#疏-17" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“上穷吝”者，处於上穷，所以遇角而吝也。</p>',67)])])}const m=e(l,[["render",n]]);export{p as __pageData,m as default};
